  `asistencia` float DEFAULT NULL,
  `apoyo_psicosocial` tinyint(1) DEFAULT NULL,
  `rol` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `correo` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
